SourceCode.Declaration:
/// <summary>
/// The TFMTableNameAttribute class is an attribute to register with your classes, that binds the class to a certain table, which can be used as a way to construct the right corresponding class, when you have a specific table buffer on your hands.
/// </summary>
public class TFMTableNameAttribute extends SysAttribute implements SysExtensionIAttribute
{
    TableName       tableName;
    TFMOrderTypes   orderType;


}

Method.Source:
void new(TableName _tableName, TFMOrderTypes _type = '')
{
    super();

    tableName = _tableName;
    orderType = _type;

}

///<summary>
/// Returns the key used for storing cached data for this attribute.
/// </summary>
/// <returns>
/// A string representing the cache key.
/// </returns>
public str parmCacheKey()
{
    return classStr(TFMTableNameAttribute)+';'+tableName+';'+orderType;
}

public TableName parmTableName(TableName _tableName = tableName)
{
    tableName = _tableName;

    return tableName;
}

public TFMOrderTypes parmOrderType(TFMOrderTypes _type = orderType)
{
    orderType = _type;

    return orderType;
}

///<summary>
/// Determines if the same instance should be returned by the extension framework.
/// </summary>
/// <returns>
/// true if the same instance should be returned; otherwise false.
/// </returns>
public boolean useSingleton()
{
    return false;
}
